{
  "name": "ISEG高压电源模块",
  "name_en": "ISEG high-voltage power supply module",
  "manufacturer": "iseg Spezialelektronik GmbH",
  "description": "这是一种多通道高压电源模块，用于为实验中的探测器、光电倍增管等器件提供和监测稳定高压。设备支持通道管理、限压限流、斜坡速度、状态寄存器、事件寄存器以及温度和内部供电监测，常用于核物理、粒子探测和其他需要精密高压偏置的实验系统。",
  "description_en": "This is a multi-channel high-voltage power supply module used to provide and monitor stable high voltage for laboratory devices such as detectors and photomultiplier tubes. It supports channel management, voltage and current limits, ramp speed settings, status and event registers, and monitoring of temperature and internal supply rails, making it suitable for nuclear physics, particle detection, and other experiments requiring precise HV biasing.",
  "tag_hints": [
    "high-voltage power supply",
    "multi-channel HV module",
    "detector bias",
    "photomultiplier tube bias",
    "voltage ramp control",
    "current limit",
    "CAN bus communication",
    "module status monitoring"
  ],
  "actions": [
    {
      "action_name": "auto-channel",
      "description": "获取指定通道。",
      "description_en": "Get a specified channel."
    },
    {
      "action_name": "auto-number_of_channels",
      "description": "获取通道数量。",
      "description_en": "Get the number of channels."
    },
    {
      "action_name": "auto-channels",
      "description": "获取全部通道。",
      "description_en": "Get all channels."
    },
    {
      "action_name": "auto-firmware_release",
      "description": "获取固件版本号。",
      "description_en": "Get the firmware release."
    },
    {
      "action_name": "auto-module_status",
      "description": "获取模块状态。",
      "description_en": "Get the module status."
    },
    {
      "action_name": "auto-filter_averaging_steps",
      "description": "获取或设置数字滤波平均步数。",
      "description_en": "Get or set the digital filter averaging steps."
    },
    {
      "action_name": "auto-kill_enable",
      "description": "获取或设置kill功能使能状态。",
      "description_en": "Get or set the kill function enable state."
    },
    {
      "action_name": "auto-adjustment",
      "description": "获取或设置精细调节功能状态。",
      "description_en": "Get or set the fine adjustment state."
    },
    {
      "action_name": "auto-module_can_address",
      "description": "获取或设置模块CAN地址。",
      "description_en": "Get or set the module CAN address."
    },
    {
      "action_name": "auto-module_can_bitrate",
      "description": "获取或设置模块CAN比特率。",
      "description_en": "Get or set the module CAN bitrate."
    },
    {
      "action_name": "auto-serial_baud_rate",
      "description": "获取或设置串口波特率。",
      "description_en": "Get or set the serial baud rate."
    },
    {
      "action_name": "auto-serial_echo_enable",
      "description": "获取或设置串口回显状态。",
      "description_en": "Get or set the serial echo state."
    },
    {
      "action_name": "auto-serial_echo_enabled",
      "description": "获取串口回显已启用状态。",
      "description_en": "Get whether serial echo is enabled."
    },
    {
      "action_name": "auto-serial_echo_disabled",
      "description": "获取串口回显已禁用状态。",
      "description_en": "Get whether serial echo is disabled."
    },
    {
      "action_name": "auto-module_voltage_limit",
      "description": "获取模块电压限值。",
      "description_en": "Get the module voltage limit."
    },
    {
      "action_name": "auto-module_current_limit",
      "description": "获取模块电流限值。",
      "description_en": "Get the module current limit."
    },
    {
      "action_name": "auto-module_voltage_ramp_speed",
      "description": "获取模块电压斜坡速度。",
      "description_en": "Get the module voltage ramp speed."
    },
    {
      "action_name": "auto-module_current_ramp_speed",
      "description": "获取模块电流斜坡速度。",
      "description_en": "Get the module current ramp speed."
    },
    {
      "action_name": "auto-module_control_register",
      "description": "获取模块控制寄存器。",
      "description_en": "Get the module control register."
    },
    {
      "action_name": "auto-module_status_register",
      "description": "获取模块状态寄存器。",
      "description_en": "Get the module status register."
    },
    {
      "action_name": "auto-module_event_status_register",
      "description": "获取模块事件状态寄存器。",
      "description_en": "Get the module event status register."
    },
    {
      "action_name": "auto-module_event_mask_register",
      "description": "获取或设置模块事件屏蔽寄存器。",
      "description_en": "Get or set the module event mask register."
    },
    {
      "action_name": "auto-module_event_channel_status_register",
      "description": "获取模块通道事件状态寄存器。",
      "description_en": "Get the module event channel status register."
    },
    {
      "action_name": "auto-module_event_channel_mask_register",
      "description": "获取或设置模块通道事件屏蔽寄存器。",
      "description_en": "Get or set the module event channel mask register."
    },
    {
      "action_name": "auto-module_supply_voltage",
      "description": "获取模块各路电源电压。",
      "description_en": "Get the module supply voltages."
    },
    {
      "action_name": "auto-module_supply_voltage_p24v",
      "description": "获取模块+24V电源电压。",
      "description_en": "Get the module +24 V supply voltage."
    },
    {
      "action_name": "auto-module_supply_voltage_n24v",
      "description": "获取模块-24V电源电压。",
      "description_en": "Get the module -24 V supply voltage."
    },
    {
      "action_name": "auto-module_supply_voltage_p5v",
      "description": "获取模块+5V电源电压。",
      "description_en": "Get the module +5 V supply voltage."
    },
    {
      "action_name": "auto-module_supply_voltage_p3v",
      "description": "获取模块+3.3V内部电源电压。",
      "description_en": "Get the module +3.3 V internal supply voltage."
    },
    {
      "action_name": "auto-module_supply_voltage_p12v",
      "description": "获取模块+12V内部电源电压。",
      "description_en": "Get the module +12 V internal supply voltage."
    },
    {
      "action_name": "auto-module_supply_voltage_n12v",
      "description": "获取模块-12V内部电源电压。",
      "description_en": "Get the module -12 V internal supply voltage."
    },
    {
      "action_name": "auto-module_temperature",
      "description": "获取模块温度。",
      "description_en": "Get the module temperature."
    },
    {
      "action_name": "auto-setvalue_changes_counter",
      "description": "获取设定值变化计数器。",
      "description_en": "Get the setvalue changes counter."
    },
    {
      "action_name": "auto-firmware_name",
      "description": "获取固件名称。",
      "description_en": "Get the firmware name."
    },
    {
      "action_name": "auto-id_string",
      "description": "获取设备标识字符串。",
      "description_en": "Get the device ID string."
    },
    {
      "action_name": "auto-instruction_set",
      "description": "获取指令集信息。",
      "description_en": "Get the instruction set."
    },
    {
      "action_name": "auto-enter_configuration_mode",
      "description": "进入配置模式以修改CAN参数。",
      "description_en": "Enter configuration mode to modify CAN settings."
    },
    {
      "action_name": "auto-exit_configuration_mode",
      "description": "退出配置模式并返回正常模式。",
      "description_en": "Exit configuration mode and return to normal mode."
    },
    {
      "action_name": "auto-set_serial_echo_enabled",
      "description": "启用串口回显。",
      "description_en": "Enable serial echo."
    },
    {
      "action_name": "auto-set_serial_echo_disabled",
      "description": "禁用串口回显。",
      "description_en": "Disable serial echo."
    },
    {
      "action_name": "auto-reset_module_event_status",
      "description": "复位模块事件状态寄存器。",
      "description_en": "Reset the module event status register."
    },
    {
      "action_name": "auto-clear_module_event_status_bits",
      "description": "清除模块事件状态寄存器中的指定位。",
      "description_en": "Clear specified bits in the module event status register."
    },
    {
      "action_name": "auto-clear_all_event_status_registers",
      "description": "清除所有事件状态寄存器。",
      "description_en": "Clear all event status registers."
    },
    {
      "action_name": "auto-reset_to_save_values",
      "description": "将模块复位到已保存的参数值。",
      "description_en": "Reset the module to the saved values."
    },
    {
      "action_name": "auto-set_command_set",
      "description": "设置模块使用的命令集。",
      "description_en": "Set the command set used by the module."
    },
    {
      "action_name": "auto-local_lockout",
      "description": "锁定本地操作界面。",
      "description_en": "Lock out the local interface."
    },
    {
      "action_name": "auto-goto_local",
      "description": "切换到本地操作模式。",
      "description_en": "Switch to local mode."
    }
  ]
}

